function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? pick(900, 1000) : pick(1, 9);
  const top = size === 'large' || rand() < 0.2 ? 1000 : pick(1, 12);
  const shape = rand();
  const nums = Array.from({ length: n }, () => pick(0, top));
  if (shape < 0.25) nums.sort((a, b) => a - b);
  else if (shape < 0.5) nums.sort((a, b) => b - a);
  if (shape < 0.5) {
    const swaps = size === 'large' ? 40 : pick(0, 2);
    for (let k = 0; k < swaps; k++) {
      const i = pick(0, n - 1), j = pick(0, n - 1);
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  return [nums];
}
